cd /app/documents; for y in 2023 2024 2025; do for f in w2 1099-int 1099-b_1 1099-b_2; do echo "=== $y $f pages: $(pdfinfo $y/$f.pdf | grep Pages)"; python3 -I -c "
import pypdf,sys
r=pypdf.PdfReader(sys.argv[1])
f=r.get_fields() or {}
for k,v in f.items():
  val=v.get('/V')
  if val not in (None,'','/Off'): print(' ',k,'=',val)
" $y/$f.pdf; done; done
